import streamlit as st
from supabase import create_client, Client
from datetime import datetime
from zoneinfo import ZoneInfo

st.set_page_config(
    page_title="남김일기",
    page_icon="🍀",
    layout="wide",
    initial_sidebar_state="collapsed",
)

# ── Supabase 연결 ─────────────────────────────────────────────
# Streamlit Cloud의 Settings > Secrets에 아래 내용을 입력하세요.
# SUPABASE_URL = "프로젝트 URL"
# SUPABASE_KEY = "anon public key"
#
# Supabase SQL Editor에서 아래 SQL을 한 번 실행하세요.
#
# create table if not exists food_diaries (
#   id bigint generated by default as identity primary key,
#   author text not null,
#   mood text not null,
#   content text not null,
#   created_at timestamptz not null default now()
# );
#
# create table if not exists diary_reads (
#   id bigint generated by default as identity primary key,
#   diary_id bigint not null references food_diaries(id) on delete cascade,
#   reader text not null,
#   created_at timestamptz not null default now(),
#   unique (diary_id, reader)
# );
#
# 수업/모둠용 간단 공유 앱을 위한 설정입니다.
# 아래 두 테이블의 RLS를 비활성화해야 anon key로 읽기/쓰기가 가능합니다.
# 실제 개인정보나 민감한 내용은 올리지 마세요.
# alter table food_diaries disable row level security;
# alter table diary_reads disable row level security;

st.markdown("""
<style>
@import url('https://fonts.googleapis.com/css2?family=Pretendard:wght@400;500;600;700;800&display=swap');
html, body, [class*="css"] { font-family: Pretendard, sans-serif; }
.stApp { background: #F6F8F4; }
.block-container { max-width: 980px; padding-top: 1.1rem; padding-bottom: .8rem; }
header, footer, #MainMenu {visibility: hidden;}
h1, h2, h3, p { color: #26352B; }
.hero {
  background: linear-gradient(115deg, #E5F0E3, #F2F5E9);
  border: 1px solid #DCE8D8; border-radius: 20px;
  padding: 16px 20px; margin-bottom: 12px;
}
.hero-title { font-size: 1.55rem; font-weight: 800; margin: 0; color: #294A35; }
.hero-sub { font-size: .86rem; color: #637466; margin: 4px 0 0 0; }
.panel {
  background: white; border: 1px solid #E6EBE2;
  border-radius: 17px; padding: 14px 16px;
}
.diary {
  background: white; border: 1px solid #E8EDE5;
  border-radius: 14px; padding: 11px 13px; margin-bottom: 8px;
}
.diary-meta { color: #718074; font-size: .76rem; }
.diary-text { color: #2D3A30; font-size: .91rem; line-height: 1.42; white-space: pre-wrap; }
.mood { font-size: .82rem; font-weight: 700; color: #48664E; }
div.stButton > button {
  border-radius: 11px; min-height: 2.35rem; font-weight: 650;
}
div[data-testid="stTextInput"] input, div[data-testid="stTextArea"] textarea {
  border-radius: 11px;
}
div[data-testid="stVerticalBlock"] > div:has(> div.stButton) { gap: .25rem; }
.small-note { color: #7A877B; font-size: .75rem; }
@media (max-width: 640px) {
  .block-container { padding: .65rem .65rem .5rem .65rem; }
  .hero { padding: 12px 14px; border-radius: 15px; margin-bottom: 8px; }
  .hero-title { font-size: 1.25rem; }
  .hero-sub { font-size: .76rem; }
  .panel { padding: 10px 11px; border-radius: 14px; }
  .diary { padding: 9px 10px; margin-bottom: 6px; }
  .diary-text { font-size: .84rem; }
}
</style>
""", unsafe_allow_html=True)

st.markdown("""
<div class="hero">
  <p class="hero-title">🍀 남김일기</p>
  <p class="hero-sub">남은 음식 활용 경험을 나누고, 서로의 기록을 확인해요.</p>
</div>
""", unsafe_allow_html=True)

# ── 설정 확인 ────────────────────────────────────────────────
try:
    supabase_url = st.secrets["SUPABASE_URL"]
    supabase_key = st.secrets["SUPABASE_KEY"]
    supabase: Client = create_client(supabase_url, supabase_key)
except Exception:
    st.error("아직 데이터베이스가 연결되지 않았어요. 아래 안내대로 Supabase 정보를 등록해 주세요.")
    with st.expander("처음 설정하는 방법", expanded=True):
        st.markdown("""
1. [Supabase](https://supabase.com/)에서 무료 프로젝트를 만들어요.
2. 왼쪽 **SQL Editor**에서 이 파일 맨 위 주석의 SQL을 실행해요.
3. **Project Settings → API**에서 Project URL과 anon public key를 복사해요.
4. GitHub에 앱을 올린 뒤 Streamlit Cloud의 **App → Settings → Secrets**에 아래처럼 입력해요.

```toml
SUPABASE_URL = "복사한 Project URL"
SUPABASE_KEY = "복사한 anon public key"
```
        """)
    st.stop()

# ── 작성자 이름 ──────────────────────────────────────────────
with st.container():
    name_col, refresh_col = st.columns([4, 1])
    with name_col:
        writer = st.text_input("내 이름", placeholder="이름 또는 별명", max_chars=16, label_visibility="collapsed")
    with refresh_col:
        if st.button("새로고침 ↻", use_container_width=True):
            st.rerun()

left, right = st.columns([0.92, 1.08], gap="medium")

# ── 일기 작성 ────────────────────────────────────────────────
with left:
    st.markdown('<div class="panel">', unsafe_allow_html=True)
    st.markdown("#### ✍️ 오늘의 남김일기")
    moods = ["😊 뿌듯해요", "😋 맛있었어요", "💡 아이디어가 생겼어요", "🤔 아쉬웠어요", "🌱 환경을 지켰어요"]
    mood = st.selectbox("오늘의 기분", moods, label_visibility="collapsed")
    content = st.text_area(
        "일기 내용",
        placeholder="남은 음식을 어떻게 활용했나요?\n예: 남은 밥으로 맛있는 볶음밥을 만들었어요!",
        height=112,
        max_chars=300,
        label_visibility="collapsed",
    )
    st.caption("음식 활용 방법과 느낀 점을 짧게 적어 보세요.")
    if st.button("일기 올리기  ✨", type="primary", use_container_width=True):
        if not writer.strip():
            st.warning("먼저 이름을 입력해 주세요.")
        elif not content.strip():
            st.warning("일기 내용을 입력해 주세요.")
        else:
            try:
                supabase.table("food_diaries").insert({
                    "author": writer.strip(),
                    "mood": mood,
                    "content": content.strip(),
                }).execute()
                st.success("일기를 공유했어요!")
                st.rerun()
            except Exception as e:
                st.error("일기를 저장하지 못했어요. 데이터베이스 설정을 확인해 주세요.")
    st.markdown('</div>', unsafe_allow_html=True)

# ── 서로의 일기 / 확인 표시 ──────────────────────────────────
with right:
    st.markdown('<div class="panel">', unsafe_allow_html=True)
    st.markdown("#### 📚 서로의 일기")
    if not writer.strip():
        st.info("이름을 입력하면 다른 사람의 일기를 확인할 수 있어요.")
    else:
        try:
            diary_result = (
                supabase.table("food_diaries")
                .select("*")
                .order("created_at", desc=True)
                .limit(12)
                .execute()
            )
            diaries = diary_result.data or []
            if not diaries:
                st.caption("아직 작성된 일기가 없어요. 첫 번째 일기를 남겨 보세요!")
            else:
                for diary in diaries:
                    diary_id = diary["id"]
                    reads_result = (
                        supabase.table("diary_reads")
                        .select("reader")
                        .eq("diary_id", diary_id)
                        .execute()
                    )
                    readers = [item["reader"] for item in (reads_result.data or [])]
                    read_by_me = writer.strip() in readers
                    try:
                        created = datetime.fromisoformat(diary["created_at"].replace("Z", "+00:00"))
                        date_label = created.astimezone(ZoneInfo("Asia/Seoul")).strftime("%m/%d %H:%M")
                    except Exception:
                        date_label = "최근 작성"

                    st.markdown(
                        f'<div class="diary">'
                        f'<div class="diary-meta">{diary["author"]} · {date_label}</div>'
                        f'<div class="mood">{diary["mood"]}</div>'
                        f'<div class="diary-text">{diary["content"]}</div>'
                        f'</div>',
                        unsafe_allow_html=True,
                    )
                    status_col, button_col = st.columns([1.25, 1])
                    if read_by_me:
                        status_col.caption("✓ 내가 확인한 일기")
                    elif diary["author"] == writer.strip():
                        status_col.caption("내가 작성한 일기")
                    else:
                        status_col.caption(f"확인한 사람 {len(readers)}명")
                    if diary["author"] != writer.strip() and not read_by_me:
                        if button_col.button("읽었어요 ✓", key=f"read_{diary_id}", use_container_width=True):
                            try:
                                supabase.table("diary_reads").insert({
                                    "diary_id": diary_id,
                                    "reader": writer.strip(),
                                }).execute()
                                st.rerun()
                            except Exception:
                                st.warning("확인 표시를 저장하지 못했어요. 이미 확인했는지 새로고침해 주세요.")
                    elif diary["author"] != writer.strip():
                        button_col.caption("확인 완료 ✓")
        except Exception:
            st.error("일기를 불러오지 못했어요. Supabase 테이블과 권한 설정을 확인해 주세요.")
    st.markdown('</div>', unsafe_allow_html=True)

st.markdown(
    '<p class="small-note" style="text-align:center;margin-top:8px;">'
    '함께 나누면 음식물 쓰레기는 줄고, 아이디어는 늘어요 🌿'
    '</p>',
    unsafe_allow_html=True,
)
